-- Repair: author-translated Russian prompts for production cards whose ru
-- locale carried answer text standing in for the question (legacy imports of
-- cards without an explicit Question (RU); translator skipped existing rows).
-- Projection-level repair: no files, no revisions, no content_hash changes.
begin;

create temp table ru_fixes(stable_key text, prompt text) on commit drop;

create temp table repaired on commit drop as
with updated as (
	update content.question_locale l
	set prompt = f.prompt
	from ru_fixes f
	join content.question q on q.stable_key = f.stable_key
	join content.question_revision r on r.id = q.current_revision_id
	join content.workspace w on w.id = q.workspace_id and w.stable_key = 'fluent-interview'
	where l.revision_id = r.id and l.locale = 'ru'
	  and q.status = 'published' and q.content_kind = 'production'
	  and (trim(l.prompt) = '' or trim(l.prompt) = trim(coalesce(l.short_answer, '')))
	returning l.id, l.revision_id
)
select * from updated;

select q.workspace_id, 'question_locale', q.id, 'question.locale.translated',
       'handoff-content-phase1-author-ru',
       jsonb_build_object('stable_key', q.stable_key, 'revision_id', rep.revision_id::text,
                          'provider', 'author-ru-prompt-repair')
from repaired rep
join content.question_locale l on l.id = rep.id
join content.question_revision r on r.id = l.revision_id
join content.question q on q.id = r.question_id;

select 'question_locale', q.id, 'question.locale.translated',
       'repair-ru-prompt:' || r.id::text,
       jsonb_build_object('stable_key', q.stable_key, 'revision_id', r.id::text,
                          'locale', 'ru', 'provider', 'author-ru-prompt-repair',
                          'actor', 'handoff-content-phase1')
from repaired rep
join content.question_locale l on l.id = rep.id
join content.question_revision r on r.id = l.revision_id
join content.question q on q.id = r.question_id
on conflict (idempotency_key) do nothing;

commit;

select count(*) as still_degenerate
from content.question q
join content.question_revision r on r.id = q.current_revision_id
join content.question_locale l on l.revision_id = r.id and l.locale = 'ru'
where q.status='published' and q.content_kind='production'
  and (trim(l.prompt)='' or trim(l.prompt)=trim(coalesce(l.short_answer,'')));
